package com.pridesys.ticketing.repository;
import com.pridesys.ticketing.dto.UsersProjectsDtos; import com.pridesys.ticketing.entity.ModuleRecord; import java.sql.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class ModuleRepository { private final JdbcTemplate jdbc; public ModuleRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public List<ModuleRecord> findByProject(long p){return jdbc.query("SELECT id,project_id,name,description,active FROM modules WHERE project_id=? ORDER BY name",this::map,p);} public long create(long p,UsersProjectsDtos.CreateModuleRequest r){var h=new org.springframework.jdbc.support.GeneratedKeyHolder();jdbc.update(c->{var q=c.prepareStatement("INSERT INTO modules(project_id,name,description) VALUES (?,?,?)",Statement.RETURN_GENERATED_KEYS);q.setLong(1,p);q.setString(2,r.name().trim());q.setString(3,r.description());return q;},h);return h.getKey().longValue();}
 public void update(long id,UsersProjectsDtos.UpdateModuleRequest r){jdbc.update("UPDATE modules SET name=?,description=?,active=COALESCE(?,active) WHERE id=?",r.name().trim(),r.description(),r.active(),id);} public void delete(long id){jdbc.update("DELETE FROM modules WHERE id=?",id);} private ModuleRecord map(ResultSet r,int n)throws SQLException{return new ModuleRecord(r.getLong("id"),r.getLong("project_id"),r.getString("name"),r.getString("description"),r.getBoolean("active"));}}
